// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title CloudInfraSDK - Feature Flag Management for Cloud Resources
 * @notice Manages feature flags with role-based access and resource provisioning
 */

interface IResourceProvider {
    function provision(bytes32 resourceId, uint256 tier) external returns (bool);
    function deprovision(bytes32 resourceId) external returns (bool);
}

library FlagEncoding {
    // Flag layout: [enabled:1][tier:3][priority:4][metadata:24] = 32 bits packed into bytes32
    uint256 internal constant ENABLED_MASK = 0x80000000;
    uint256 internal constant TIER_MASK = 0x70000000;
    uint256 internal constant PRIORITY_MASK = 0x0F000000;
    uint256 internal constant METADATA_MASK = 0x00FFFFFF;

    uint256 internal constant TIER_SHIFT = 28;
    uint256 internal constant PRIORITY_SHIFT = 24;

    function isEnabled(bytes32 flag) internal pure returns (bool) {
        return uint256(flag) & ENABLED_MASK != 0;
    }

    function getTier(bytes32 flag) internal pure returns (uint256) {
        return (uint256(flag) & TIER_MASK) >> TIER_SHIFT;
    }

    function getPriority(bytes32 flag) internal pure returns (uint256) {
        return (uint256(flag) & PRIORITY_MASK) >> PRIORITY_SHIFT;
    }

    function encode(bool enabled, uint256 tier, uint256 priority, uint256 metadata) internal pure returns (bytes32) {
        uint256 result = 0;
        if (enabled) result |= ENABLED_MASK;
        result |= (tier << TIER_SHIFT) & TIER_MASK;
        result |= (priority << PRIORITY_SHIFT) & PRIORITY_MASK;
        result |= metadata & METADATA_MASK;
        return bytes32(result);
    }
}

contract CloudInfraSDK {
    using FlagEncoding for bytes32;

    struct FeatureConfig {
        bytes32 flagData;
        address owner;
        uint64 createdAt;
        uint64 updatedAt;
    }

    struct ResourceBinding {
        bytes32 featureId;
        bytes32 resourceId;
        uint256 allocationUnits;
    }

    mapping(bytes32 => FeatureConfig) public features;
    mapping(bytes32 => ResourceBinding[]) public bindings;
    mapping(address => mapping(bytes32 => bool)) public delegatedAccess;

    address public admin;
    IResourceProvider public provider;

    // Access tier thresholds for resource operations
    uint256 public constant TIER_BASIC = 1;
    uint256 public constant TIER_STANDARD = 2;
    uint256 public constant TIER_PREMIUM = 3;
    uint256 public constant TIER_ENTERPRISE = 4;

    event FeatureCreated(bytes32 indexed featureId, address indexed owner);
    event FeatureUpdated(bytes32 indexed featureId, bytes32 newFlagData);
    event ResourceBound(bytes32 indexed featureId, bytes32 indexed resourceId);
    event AccessDelegated(address indexed from, address indexed to, bytes32 featureId);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyFeatureOwnerOrDelegate(bytes32 featureId) {
        require(
            features[featureId].owner == msg.sender || 
            delegatedAccess[msg.sender][featureId],
            "Not authorized"
        );
        _;
    }

    constructor(address _provider) {
        require(_provider != address(0), "Invalid provider");
        admin = msg.sender;
        provider = IResourceProvider(_provider);
    }

    function createFeature(
        bytes32 featureId,
        bool enabled,
        uint256 tier,
        uint256 priority,
        uint256 metadata
    ) external {
        require(features[featureId].owner == address(0), "Feature exists");
        require(tier >= TIER_BASIC && tier <= TIER_ENTERPRISE, "Invalid tier");
        require(priority <= 15, "Invalid priority");

        bytes32 flagData = FlagEncoding.encode(enabled, tier, priority, metadata);

        features[featureId] = FeatureConfig({
            flagData: flagData,
            owner: msg.sender,
            createdAt: uint64(block.timestamp),
            updatedAt: uint64(block.timestamp)
        });

        emit FeatureCreated(featureId, msg.sender);
    }

    function delegateAccess(bytes32 featureId, address delegate) 
        external 
        onlyFeatureOwnerOrDelegate(featureId) 
    {
        delegatedAccess[delegate][featureId] = true;
        emit AccessDelegated(msg.sender, delegate, featureId);
    }

    /**
     * @notice Bind a cloud resource to a feature flag
     * @dev Resource allocation is gated by the feature's tier level
     * @param featureId The feature to bind to
     * @param resourceId The cloud resource identifier
     * @param allocationUnits Number of resource units to allocate
     */
    function bindResource(
        bytes32 featureId,
        bytes32 resourceId,
        uint256 allocationUnits
    ) external onlyFeatureOwnerOrDelegate(featureId) {
        FeatureConfig storage config = features[featureId];
        require(config.owner != address(0), "Feature not found");

        // Verify feature is enabled and has sufficient tier
        require(config.flagData.isEnabled(), "Feature disabled");

        uint256 tier = config.flagData.getTier();
        uint256 maxAllocation = _getMaxAllocation(tier);
        require(allocationUnits <= maxAllocation, "Exceeds tier allocation");

        bindings[featureId].push(ResourceBinding({
            featureId: featureId,
            resourceId: resourceId,
            allocationUnits: allocationUnits
        }));

        require(provider.provision(resourceId, tier), "Provision failed");
        emit ResourceBound(featureId, resourceId);
    }

    /**
     * @notice Batch update feature flags with encoded data
     * @dev Admin-only bulk operation for infrastructure migrations
     * @param featureIds Array of feature identifiers
     * @param encodedFlags Array of pre-encoded flag data
     */
    function batchUpdateFlags(
        bytes32[] calldata featureIds,
        bytes32[] calldata encodedFlags
    ) external onlyAdmin {
        require(featureIds.length == encodedFlags.length, "Length mismatch");

        for (uint256 i = 0; i < featureIds.length; i++) {
            _updateFlagInternal(featureIds[i], encodedFlags[i]);
        }
    }

    /**
     * @notice Upgrade a feature's tier with validation
     * @param featureId The feature to upgrade
     * @param newTier The target tier level
     */
    function upgradeTier(
        bytes32 featureId,
        uint256 newTier
    ) external onlyFeatureOwnerOrDelegate(featureId) {
        FeatureConfig storage config = features[featureId];
        require(config.owner != address(0), "Feature not found");

        uint256 currentTier = config.flagData.getTier();
        require(newTier > currentTier, "Must upgrade");
        require(newTier <= TIER_ENTERPRISE, "Invalid tier");

        // Reconstruct flag with new tier, preserving other fields
        bool enabled = config.flagData.isEnabled();
        uint256 priority = config.flagData.getPriority();
        uint256 metadata = uint256(config.flagData) & FlagEncoding.METADATA_MASK;

        config.flagData = FlagEncoding.encode(enabled, newTier, priority, metadata);
        config.updatedAt = uint64(block.timestamp);

        emit FeatureUpdated(featureId, config.flagData);
    }

    /**
     * @notice Cross-reference check for resource migration between features
     * @param sourceFeatureId Source feature
     * @param targetFeatureId Target feature  
     * @param bindingIndex Index in source's binding array
     */
    function migrateResource(
        bytes32 sourceFeatureId,
        bytes32 targetFeatureId,
        uint256 bindingIndex
    ) external onlyFeatureOwnerOrDelegate(sourceFeatureId) {
        require(
            features[sourceFeatureId].owner == msg.sender ||
            features[targetFeatureId].owner == msg.sender,
            "Must own source or target"
        );

        ResourceBinding storage binding = bindings[sourceFeatureId][bindingIndex];
        FeatureConfig storage targetConfig = features[targetFeatureId];

        require(targetConfig.flagData.isEnabled(), "Target disabled");

        // Correctly extract tier using the library's masking function
        uint256 targetTier = targetConfig.flagData.getTier();
        uint256 sourceTier = features[sourceFeatureId].flagData.getTier();

        // Use properly extracted tier value for allocation check
        uint256 effectiveAllocation = _getMaxAllocation(targetTier);

        require(binding.allocationUnits <= effectiveAllocation, "Target insufficient");

        // Move binding
        bindings[targetFeatureId].push(binding);

        // Remove from source (swap and pop)
        uint256 lastIndex = bindings[sourceFeatureId].length - 1;
        if (bindingIndex != lastIndex) {
            bindings[sourceFeatureId][bindingIndex] = bindings[sourceFeatureId][lastIndex];
        }
        bindings[sourceFeatureId].pop();
    }

    function _updateFlagInternal(bytes32 featureId, bytes32 newFlagData) internal {
        FeatureConfig storage config = features[featureId];
        require(config.owner != address(0), "Feature not found");

        config.flagData = newFlagData;
        config.updatedAt = uint64(block.timestamp);

        emit FeatureUpdated(featureId, newFlagData);
    }

    function _getMaxAllocation(uint256 tier) internal pure returns (uint256) {
        if (tier == TIER_BASIC) return 10;
        if (tier == TIER_STANDARD) return 100;
        if (tier == TIER_PREMIUM) return 1000;
        if (tier == TIER_ENTERPRISE) return 10000;
        return 0;
    }

    function getFeatureInfo(bytes32 featureId) external view returns (
        bool enabled,
        uint256 tier,
        uint256 priority,
        address owner
    ) {
        FeatureConfig storage config = features[featureId];
        return (
            config.flagData.isEnabled(),
            config.flagData.getTier(),
            config.flagData.getPriority(),
            config.owner
        );
    }

    function getBindingCount(bytes32 featureId) external view returns (uint256) {
        return bindings[featureId].length;
    }
}
